 static void SpawnDirect(){EnsureInformation();if(direct!=null||fastPending)throw new ArgumentException("正在准备空投，请稍候。");var current=Singleton<GameWorld>.Instance;var player=current?.MainPlayer;if(!RaidClock.Active||current==null||player?.HealthController?.IsAlive!=true)throw new ArgumentException("需要战局内存活的玩家。");if(Time.unscaledTime<cooldown)throw new ArgumentException("请稍候再生成。");if(custom&&!NextRaidLoot.ServerStatus.StartsWith("服务端模块已就绪",StringComparison.Ordinal))throw new ArgumentException("自定义空投需要服务端模块就绪。");Save();var processor=current.SynchronizableObjectLogicProcessor??throw new ArgumentException("空投系统尚未就绪。");var manager=Manager()??throw new ArgumentException("当前战局没有本地空投控制器。");int mask=LayerMask.GetMask("HighPolyCollider","Terrain","LowPolyCollider");if(mask==0)throw new ArgumentException("地面碰撞数据尚未就绪。");var forward=Vector3.ProjectOnPlane(player.Transform.forward,Vector3.up).normalized;var requested=player.Position+forward*2;Vector3 ground=default;bool found=false;foreach(var offset in new[]{Vector3.zero,new Vector3(2,0,0),new Vector3(-2,0,0),new Vector3(0,0,2)})if(Physics.Raycast(requested+offset+Vector3.up*2,Vector3.down,out var floor,5,mask,QueryTriggerInteraction.Ignore)&&floor.normal.y>.5f&&!Physics.CheckBox(floor.point+Vector3.up*.75f,new Vector3(.8f,.65f,.8f),Quaternion.identity,mask,QueryTriggerInteraction.Ignore)){ground=floor.point+Vector3.up*.08f;found=true;break;}if(!found)throw new ArgumentException("玩家附近没有放得下空投箱的地面。");var raw=processor.TakeFromPool(SynchronizableObjectType.AirDrop);var drop=raw?.TryCast<AirdropSynchronizableObject>()??throw new ArgumentException("未能取得空投箱。");try{processor.InitSyncObject(drop,ground,Vector3.zero,processor.TakeSynchronizedObjectId);var task=manager.InitContainerLoot(drop,null);direct=new(){World=current.Pointer,Drop=drop,Processor=processor,Task=task,Position=ground,Started=Time.unscaledTime};cooldown=Time.unscaledTime+2;notice="正在原地生成空投箱并准备物资…";}catch{processor.ReturnToPool(drop);throw;}}
 static void TickDirect(){var request=direct;if(request==null)return;if(Singleton<GameWorld>.Instance?.Pointer!=request.World||!RaidClock.Active){CancelDirect();return;}if(Time.unscaledTime-request.Started>60&&!request.Abandoned){request.Abandoned=true;notice="空投物资准备超时，正在等待清理，请检查服务端。";FeatureToasts.Show(notice);}if(!request.Task.IsCompleted)return;if(request.Abandoned){CancelDirect();return;}try{if(request.Task.IsFaulted||request.Task.IsCanceled||!request.Task.Result)throw new InvalidOperationException("空投物资生成失败。");var drop=request.Drop;drop.transform.position=request.Position;var client=drop.Logic?.TryCast<ClientAirDrop>();var server=drop.Logic?.TryCast<ServerAirDrop>()??client?.OfflineServerLogic;drop.IsStatic=true;drop.InitStaticObject();if(server!=null){server._fallingStage=EAirdropFallingStage.Landed;server._descending=false;server._velocity=Vector3.zero;var body=server.SyncObjectRigidbody;if(body!=null){if(!body.isKinematic){body.velocity=Vector3.zero;body.angularVelocity=Vector3.zero;}body.isKinematic=true;}}if(client!=null){client._fallingStage=EAirdropFallingStage.Landed;client._startFallingStage=EAirdropFallingStage.Landed;client.InitializeLandedAirdrop();client.CloseParachute();}drop.IsActive=true;Track(drop);ledger.Released(Key(drop),Elapsed);direct=null;notice="空投箱已生成在玩家附近地面。";FeatureToasts.Show(notice);}catch(Exception e){CancelDirect();notice=e.Message;FeatureToasts.Show(notice);Plugin.Self.Log.LogWarning("Direct airdrop: "+e.Message);}}
